    seleccion: ['El G-XTREME 3.0 conviene a corporaciones que buscan movilidad de hombros en ataque interior y que también pueden requerir una configuración de proximidad. El chaquetón emplea AXTION Back y AXTION Sleeve para dar longitud al alcanzar al frente; además integra YOCCO para arrastre. Frente al CLASSIX de hombro caído y al G-XCEL de espalda larga, esta plataforma se distingue por esas dos zonas AXTION y por poder pedirse en corte Straight, Tapered o Women’s.', 'La orden debe separar con precisión la versión estructural de la de proximidad y nombrar el shell seleccionado: PBI MAX 7.0, PBI MAX LP 6.0 u otra opción aprobada. Si se cotiza CROSSTECH Innovate, solicite que aparezca junto con el forro térmico y la etiqueta aplicable. Defina también corte, largos de chaquetón y pantalón, bolsillo de carga y dispositivo YOCCO; no todos los accesorios se incluyen en cada configuración.'],
