    seleccion: ['CLASSIX resuelve una dotación estructural con construcción reconocible: chaquetón de hombro caído y pantalón de tiro bajo con pretina elástica independiente. Esa combinación favorece alcance sin el patrón elástico de ATHLETIX y se diferencia del G-XCEL porque no trae espalda larga integrada. El doble pozo de manga con puño, el corte de bota inverso y la entrepierna de diamante son los elementos que conviene revisar en una muestra física.', 'En la especificación separe los bolsillos Dual-Action del chaquetón de los bolsillos opcionales del pantalón, pues no tienen la misma condición. Defina si se requiere espalda extendida, qué corte se pide —Straight o Women’s— y el conjunto de capas que acompañará la etiqueta NFPA 1970. Incluya la longitud de espalda y el sistema de tirantes; son decisiones de configuración del CLASSIX, no accesorios automáticos.'],
