    seleccion: ['G-XCEL es la alternativa Globe para quien necesita espalda larga integrada y menor volumen en el frente. El chaquetón combina patrón de manga AXTION con cuello contorneado de 3 pulgadas; por ello se separa del CLASSIX de hombro caído y del G-XTREME 3.0, cuya cobertura térmica superior y patrón AXTION responden a otra plataforma. Los bolsillos cargo con calentador de manos y la apertura amplia al forro ayudan a definir la dotación.', 'La requisición debe indicar los largos de espalda y pecho para chaquetón y pantalón, la opción de bolsillo, el material del puño telescópico y el compuesto aprobado. Si se solicita proximidad además de estructural, pida la etiqueta específica y no use la del conjunto estructural como sustituto. Confirme que la espalda larga integrada deja el espacio necesario para identificación debajo del equipo autónomo.'],
