    seleccion: ['El conjunto Forestal FPFTJ / FPFTP responde a incendio forestal con chamarra y pantalón separados en Nomex IIIA de 6.0 oz con repelente al agua. Se diferencia del Defender industrial por aplicación y del Overol de Rescate por construcción de dos piezas. La chamarra FPFTJ usa broches; el pantalón FPFTP usa cierre, de modo que la orden puede atender reposición de la pieza con mayor desgaste sin renovar todo el conjunto.', 'Sköld declara equivalencia con NFPA 1977 edición 2011, no una certificación de tercero; mantenga esa redacción en la propuesta. Especifique FPFTJ, FPFTP, tallas, ribetes y cualquier personalización antes de fabricar. Verifique que la brigada requiere protección forestal y no estructural: una prenda ligera de exterior no debe extenderse contractualmente a ataque interior o proximidad.'],
