    seleccion: ['Sköld Aproximación se destina a fundiciones, acereras, instalaciones químicas y aeropuertos con calor radiante. A diferencia de Herö, utiliza shell Kevlar aluminizado de 11 oz, rodillas con segunda capa aluminizada y forro Chambray Nomex/Kevlar de 7.5 oz. La línea se divide en FPAPROX91 para brigada, con neopreno, y FPAPROX13 profesional, con Stedair 3000 y DRD; esa distinción debe llegar intacta a la orden.', 'Solicite una sola versión, 91 o 13, con su barrera correspondiente, tallas, chaquetón, pantalón, guante FPGAP y cubrecasco EALU-R-AR cuando se requieran. La referencia del fabricante a ediciones NFPA no equivale a certificación de tercero, por lo que el expediente debe delimitar el alcance. No use una configuración de aproximación para sustituir EPP encapsulado o protección específica contra sustancias químicas.'],
