    seleccion: ['PCU50 es la cizalla Pentheon para una dotación que necesita 182 mm de apertura y capacidad publicada de cortar barra redonda S235 de 41 mm conforme a EN 13204. Con 21.6 kg lista para uso, incluida la batería, se sitúa por debajo de PCU60 en apertura y diámetro de barra, pero por encima de PCU40. Esa posición ayuda a elegirla cuando el equipo busca una cizalla principal sin ir al peso de la mayor de la línea.', 'La herramienta usa la batería PBPA288 y el fabricante la describe como cizalla inclinada. La geometría inclinada se debe evaluar en un vehículo de la flota, verificando acceso a postes y puntos de corte antes de adjudicar. Holmatro publica dos modos, uno de entrenamiento o demostración de velocidad reducida y otro Pentheon de alta velocidad; también publica Bluetooth y diagnósticos de la herramienta. Esos recursos no reemplazan estabilización del vehículo, protección de paciente ni capacitación para determinar el punto de corte. El asa giratoria de 360 grados facilita ajustar el control desde posiciones variables.'],
