    seleccion: ['PSP50 es el separador Pentheon de 725 mm de distancia y 366 kN de fuerza máxima de separación. La apertura coincide con PSP40, pero PSP50 eleva la fuerza publicada de 280 a 366 kN y pesa 21 kg lista para uso. Por tanto, no es simplemente un separador de gran apertura: es la alternativa de la misma familia cuando el comprador privilegia la fuerza máxima sin cambiar de plataforma de batería.', 'La herramienta se alimenta con PBPA288 y Holmatro publica controles de velocidad, conectividad Bluetooth y diagnóstico en la aplicación MyHolmatro. En operación, esos datos facilitan mantenimiento y planeación, pero el rescatista debe mantener el control del desplazamiento y proteger puntos de atrapamiento. Es conveniente ensayar la apertura de 725 mm con los accesorios y técnicas propias de la corporación, porque el valor no determina por sí mismo la distancia útil tras colocar puntas, cadenas o apoyos. El mango de transporte de 360 grados permite sostener el separador desde ángulos distintos. Los LEDs automáticos del asa se alimentan desde la batería principal.'],
