    seleccion: ['PRA50 aporta una carrera total de 407 mm con 136 kN de fuerza de separación durante todo el recorrido. El dato de fuerza sostenida es el criterio que lo diferencia de herramientas cuyo empuje cambia a lo largo de la carrera: permite elegir puntos de apoyo sabiendo qué valor publicado mantiene el ariete. Con 18.4 kg listo para uso, es más pesado que PRA40, pero casi duplica su carrera de 215 mm.', 'Holmatro integra PBPA288, dos modos de velocidad y doble asa de transporte. Esta última característica es relevante al posicionar el ariete desde ambos lados del vehículo o dentro de un espacio reducido, pero no reemplaza el uso de bases y extensiones compatibles. La línea Pentheon también publica una marca que señala el punto donde apoyará el ariete al extenderse; úsela para verificar colocación inicial, no como sustituto de la evaluación de estabilidad. La orden debe definir si requiere extensiones, base de ariete y equipo de estabilización, pues no se asumen incluidos con PRA50. La carga integrada prioriza las baterías que permanezcan conectadas a la herramienta.'],
