    seleccion: ['S 789 E3 Connect es la cizalla HURST de este grupo para quien necesita 205 mm de apertura y la clasificación A8/B9/C8/D9/E9/F5. Su posición frente a SC 358 es clara: la S 789 está dedicada al corte y publica una clasificación superior en los seis perfiles NFPA; frente a la R 521 no crea desplazamiento, sino que prepara los elementos que impiden el acceso. El peso publicado de 22.5 kg obliga a probarla con la postura y los relevos reales de la corporación.', 'El paquete actual E3 Connect de 9 Ah se identifica como 272989000-9C. La conectividad permite registrar datos de la herramienta, pero no cambia la necesidad de inspeccionar batería, cuchillas y control antes de cada llamada. HURST presenta el modelo en la plataforma E3 Connect, mientras que sus guías de soporte agrupan S 378/788/789/799. Exija la versión Connect y el paquete de batería exactos; una ficha de otra generación puede variar en contenido, peso o capacidades. La descarga de telemetría requiere preparar conectividad y política de mantenimiento.'],
    idealPara: ['Corte con clasificación NFPA A8/B9/C8/D9/E9/F5', 'Compañías que requieren apertura de 205 mm', 'Flotas que administran herramientas E3 Connect', 'Compra identificada por paquete de 9 Ah'],
    aConsiderar: ['La clasificación describe perfiles de prueba; no autoriza cortar componentes sin evaluación del vehículo.', 'Confirme que el paquete sea 272989000-9C y no otra presentación S 789.', 'El peso de 22.5 kg debe considerarse con batería y ergonomía de la cuadrilla.'],
