    seleccion: ['El G1 estructural conviene cuando la corporación busca un SCBA cuya alarma de fin de servicio está integrada y cuya configuración puede incorporar telemetría bidireccional. MSA publica cilindros de 2,216, 4,500 y 5,500 psi, además de duraciones nominales de 30, 45 y 60 minutos; la combinación aprobada es la que define lo recibido. Frente a una versión G1 orientada a CBRN, esta ficha se concentra en la configuración para servicio estructural y no presupone esa aprobación adicional.', 'En la orden deben aparecer presión, duración nominal, careta, regulador, módulo de energía y control, y la etiqueta de aprobación correspondiente. Los 30 minutos son la única duración que MSA asocia con el cilindro de 2,216 psi; no transfiera ese dato a otro tanque. El tiempo nominal no es aire garantizado en intervención, pues varía con el trabajo respiratorio. Verifique además que el ensamble se entregue con la aprobación SEI aplicable a la configuración solicitada.'],
    idealPara: ['Dotaciones estructurales que requieren EOSTI integrado', 'Flotas que planean telemetría bidireccional', 'Selección documentada de 30, 45 o 60 minutos', 'Reposición dentro de una plataforma MSA G1'],
    aConsiderar: ['La aprobación NFPA depende de la configuración identificada en la etiqueta.', 'La duración nominal no sustituye el control de aire durante la intervención.', 'No mezcle presiones ni componentes de una aprobación distinta en la misma partida.'],
    faqs: [{ q: '¿Qué presiones de cilindro publica MSA para G1?', a: 'MSA publica opciones de 2,216, 4,500 y 5,500 psi, sujetas a la configuración aprobada.' }, { q: '¿Dónde se integra EOSTI?', a: 'MSA identifica EOSTI como una función integrada del G1.' }, { q: '¿Cuándo cumple el PASS NFPA 1970(1982)-2025?', a: 'Cuando el G1 lleva módulos de energía y control en la configuración de aprobación NFPA.' }],
    fuentes: [{ titulo: 'MSA — información de aprobación G1 SCBA 2025 CBRN', url: 'https://docs.msasafety.com/g1scba2025cbrn/G1%202024%20CBRN%20PN%20TBD/NFPA_Approval_Information.htm' }, { titulo: 'MSA — manual G1 SCBA edición 2025 CBRN', url: 'https://docs.msasafety.com/g1scba2025cbrn/G1%202024%20CBRN%20PN%20TBD/PDF/G1_2025_CBRN_10246168.pdf' }],
    features: ['EOSTI integrado', '30, 45 o 60 min según cilindro', 'Telemetría bidireccional disponible'],
