    seleccion: ['Mavic 3 Thermal concentra cámara térmica radiométrica de 640×512, gran angular de 48 MP y tele de 12 MP en una aeronave de 920 g con hélices y sin accesorios. La escala favorece el despliegue rápido frente a Matrice 30T, pero no incluye el telémetro láser ni la carcasa IP55 de aquella. DJI publica hasta 45 minutos de vuelo sin viento; para una guardia, esa cifra se usa para diseñar relevos y retornos, no como tiempo asegurado en cada salida.', 'La térmica usa microbolómetro VOx, 30 Hz, NETD de hasta 50 mK a f/1.0 y rangos de −20 a 150 °C o 0 a 500 °C según ganancia. Puede medir punto y área, y genera R-JPEG de 16 bits además de JPEG. El tele alcanza 56× de zoom híbrido, mientras la térmica dispone de 28× digital. DJI no publica clasificación IP para Mavic 3T, por eso la selección conviene para misiones donde la portabilidad supera el requisito de operación bajo lluvia o polvo. El control DJI RC Pro Enterprise integra pantalla de 5.5 pulgadas y brillo de 1,000 nits.'],
    idealPara: ['Respuesta inicial con aeronave de 920 g', 'Búsqueda de campo con térmica radiométrica', 'Reconocimiento visual y térmico en una sola salida', 'Equipos que requieren tele de 56× híbrido'],
    aConsiderar: ['No se debe anunciar clasificación IP para Mavic 3T porque DJI no la publica en la ficha consultada.', 'Los 45 minutos corresponden a ensayo sin viento y configuración de batería especificada.', 'La medición térmica aérea requiere validar emisividad, distancia y condiciones antes de reportar una temperatura.'],
    faqs: [{ q: '¿Mavic 3 Thermal usa sensor FLIR?', a: 'No. DJI publica un microbolómetro VOx propio y no identifica un sensor FLIR.' }, { q: '¿Cuál es el peso publicado?', a: 'DJI indica 920 g con hélices y sin accesorios para Mavic 3T/3TA.' }, { q: '¿Qué archivos térmicos puede producir?', a: 'La ficha indica JPEG de 8 bits y R-JPEG de 16 bits para las imágenes térmicas.' }],
    fuentes: [{ titulo: 'DJI Enterprise — especificaciones Mavic 3 Enterprise', url: 'https://enterprise.dji.com/mavic-3-enterprise/specs' }],
    features: ['Térmica radiométrica 640×512', '920 g y hasta 45 min', 'Tele 12 MP con zoom híbrido 56×'],
