    specs: { autonomia: 'Aeronave Matrice 3D/3TD: hasta 50 min de vuelo en ensayo DJI', sensor: 'Compatible con Matrice 3D/3TD; carga térmica en Matrice 3TD', alcance: 'Radio máximo de operación: 10 km', ip: 'Dock IP55; Matrice 3D/3TD IP54', ideal: 'Operaciones automatizadas y despliegue remoto planificado', peso: '34 kg sin aeronave', extra: 'Carga de 20 a 90 % en 32 min; capacidad para una aeronave' },
    seleccion: ['Dock 2 no es una aeronave ni una cámara: es una estación de 34 kg sin aeronave, diseñada para alojar una Matrice 3D o 3TD y automatizar despliegues planificados. DJI publica IP55 para el dock e IP54 para la aeronave, un radio máximo de operación de 10 km y capacidad para una unidad. La Matrice 3TD aporta la carga térmica dentro de esa combinación; por eso no debe anunciarse que la estación, por sí sola, incorpora un sensor térmico.', 'La estación carga la aeronave apagada de 20 a 90 % en 32 minutos a 25 °C. DJI reporta hasta 50 minutos de vuelo para Matrice 3D en condiciones controladas, aunque el alcance de misión se calcula reservando batería y considera viento, velocidad y tiempo de permanencia. Frente a M30T o Mavic 3T, la ventaja no es la portabilidad sino la continuidad de una operación con sitio, energía, red, mantenimiento y procedimientos de contingencia definidos. FlightHub 2 y Cloud API pueden formar parte de la integración, pero deben solicitarse y configurarse conforme a la arquitectura de datos de la institución.'],
    idealPara: ['Vigilancia programada desde ubicación fija', 'Reconocimiento remoto con Matrice 3TD térmica', 'Operaciones que requieren carga automática', 'Instituciones con red, energía y mantenimiento dedicados'],
    aConsiderar: ['Dock 2 sólo aloja una aeronave y requiere infraestructura eléctrica y de comunicaciones en sitio.', 'El radio de 10 km y los tiempos de vuelo no sustituyen una evaluación de riesgo, cobertura y regulación local.', 'La protección IP puede degradarse con desgaste; programe inspección y mantenimiento como indica DJI.'],
    faqs: [{ q: '¿Qué aeronaves admite Dock 2?', a: 'DJI especifica Matrice 3D y Matrice 3TD para Dock 2.' }, { q: '¿Cuánto pesa la estación?', a: 'El peso total publicado es 34 kg sin aeronave.' }, { q: '¿Cuánto tarda en cargar de 20 a 90 %?', a: 'DJI publica 32 minutos a 25 °C con la aeronave apagada.' }],
    fuentes: [{ titulo: 'DJI Enterprise — especificaciones Dock 2', url: 'https://enterprise.dji.com/dock-2/specs' }, { titulo: 'DJI Enterprise — Dock 2', url: 'https://enterprise.dji.com/dock-2?from=nav&site=enterprise' }],
