    seleccion: ['USTM es la interpretación mate del casco tradicional UST: Bullard publica la carcasa Thermoglas, el sistema Sure-Lock y U-Fit con 36 ajustes de comodidad. Puede configurarse con pantalla de cuatro pulgadas, goggles ESS, visor integrado ReTrak o iluminación TrakLite. Frente al LowRider, la elección parte de la apariencia tradicional UST/USTM y no de la plataforma de altura reducida lanzada posteriormente.', 'La cotización debe nombrar USTM, no solamente UST, cuando el acabado mate es requisito, y debe separar visor, goggles, luz y frontal de cuero como componentes configurables. Revise que suspensión, retenedor, cubrenuca y protector facial sean piezas Bullard aprobadas: la propia instrucción advierte que sustituir componentes puede invalidar la conformidad. Para descontaminación y reinspección, siga el manual de la configuración entregada.'],
