    seleccion: ['UST LowRider está orientado al bombero que prioriza altura de uso baja y centro de gravedad reducido en un casco tradicional. Bullard publica un intervalo de 1.4 a 1.5 kg, U-Fit con 36 ajustes y FireFit para interiores de fácil retiro. Frente al USTM, la diferencia de compra no es sólo el acabado: LowRider se especifica con una plataforma de altura reducida y carcasa compuesta de fibra de vidrio con resina termofija.', 'Defina el color mate, el protector ReTrak y TrakLite cuando se requieran, ya que son opciones. El peso publicado varía con configuración; use el intervalo del fabricante y no una cifra única en el pliego. El casco se debe conservar con sus piezas aprobadas y su etiqueta NFPA 1970(1971) edición 2025. La altura reducida no elimina la necesidad de verificar la interfaz con máscara, capucha, cubrenuca y protección ocular seleccionada.'],
