    seleccion: ['N6A Houston es el casco de cuero Cairns que MSA identifica como conforme a NFPA 1971 edición 2018. Su rasgo de selección frente al N5A New Yorker es decisivo: el N5A se describe como OSHA, mientras N6A Houston aparece como NFPA. MSA también publica elementos blandos removibles desde septiembre de 2018, una característica que permite planear limpieza sin tratar el casco de cuero como un conjunto sin componentes sustituibles.', 'La orden debe confirmar edición de etiqueta, color, curva Bronx o Boston y los elementos blandos requeridos. No sustituya N6A por N5A cuando el requisito sea NFPA. Las piezas removibles facilitan el mantenimiento, pero no validan una reparación con componentes no autorizados. Inspeccione cuero, retención y forros conforme a las instrucciones de MSA antes de reasignar el casco tras exposición o daño.'],
