    seleccion: ['Cairns 1836 es el casco tradicional compuesto que MSA publica con 1.52 kg, visor Defender articulado y ratchet expandido y pivotante. Su sistema Shell Release permite que la tapa de impacto permanezca sobre la cabeza si el shell se desprende en circunstancias como una caída; ese diseño lo distingue de los Cairns tradicionales anteriores. Frente al N6A, cambia cuero por compuesto de fibra de vidrio y añade piezas blandas de conexión rápida para limpieza.', 'La compra debe definir visor Defender, color, tipo de liner y earlaps: las variantes de número de parte no contienen todas los mismos accesorios. MSA especifica NFPA 1971 edición 2018 en la hoja de producto; confirme la etiqueta del conjunto y los protectores oculares incluidos. El sistema de liberación no es un permiso para usar un casco dañado: inspeccione shell, tapa de impacto, retenedores y suspensión antes de regresar el equipo a servicio.'],
