const detalleSeleccionPorModelo: Record<string, string> = {
  'globe-gxtreme-3-estructural': 'El comité debe revisar el cuello contorneado, los puños telescópicos y la apertura al forro propios del G-XTREME 3.0. Esos elementos ayudan a distinguir su especificación frente a otros Globe antes de definir cantidades, medidas corporales y componentes de cada usuario.',
  'globe-athletix-estructural': 'Durante la evaluación de ATHLETIX, compruebe que los paneles elásticos, codos articulados y puños dobles mantengan el ajuste esperado con la capucha elegida. La silueta atlética sólo conserva su propósito cuando chaquetón, pantalón y tallas se piden como conjunto coordinado.',
  'globe-classix-estructural': 'La muestra CLASSIX debe incluir el pantalón con pretina elástica, corte de bota inverso y entrepierna de diamante. Así se puede decidir si el patrón tradicional de hombro caído responde mejor a la dotación que las alternativas Globe de patrón elástico o espalda integrada.',
  'globe-gxcel-estructural': 'Al definir G-XCEL, establezca si la espalda integrada recibirá letras, qué largo requiere el usuario y cómo quedará el espacio debajo del equipo autónomo. Ese solape posterior es el criterio práctico que separa esta plataforma de las otras opciones Globe estructurales.',
  'globe-proximity-arff': 'La compra de Globe Proximity debe incluir un programa de inspección visual de la película aluminizada y criterios de retiro por daño, contaminación o pérdida de reflectividad. Esos controles son particularmente relevantes para un shell destinado a reflejar calor radiante y no para uso cotidiano estructural.',
  'traje-lion-v-force': 'V-Force requiere seleccionar la familia de forro compatible con IsoDri y documentar qué zonas de humedad serán parte de la configuración. El comprador también debe definir si la corporación necesita manga raglán simple o complementos de movilidad disponibles para esa plataforma LION. La orden debe identificar expresamente V-Force para no mezclar sus alternativas con RedZone o EVO.',
  'traje-lion-redzone': 'RedZone debe contratarse como sistema de interfaces: capucha, puños, cintura, botas y cierres requieren integración completa. Solicite que el proveedor detalle cada zona del paquete y el procedimiento de colocación, porque una interfaz omitida cambia el resultado esperado de control de partículas.',
  'traje-lion-v-force-evo': 'Para EVO, pruebe el funcionamiento de los cierres magnéticos con los guantes institucionales y confirme que el personal reconoce su modo de cierre. Esa evaluación es exclusiva de la construcción Premium y ayuda a evitar cotizar una característica que la versión seleccionada no incorpora.',
  'traje-lion-super-deluxe': 'En Super-Deluxe, determine el nivel de refuerzo de puños, hombros, codos, rodillas y tobillos según desgaste observado por la corporación. La espalda bi-swing y los fuelles bajo axila deben conservarse compatibles con las capas seleccionadas para mantener el comportamiento Freedom Design. Distinga esta plataforma de V-Force cuando la prioridad sea su construcción Freedom Design y los refuerzos.',
  'traje-lion-engage-wildland': 'ENgage Wildland debe evaluarse con el calzado, guantes y mochila de combate forestal de la brigada. La articulación de codos y rodillas, así como sus refuerzos, se eligieron para desplazamiento exterior y deben permanecer libres de aditamentos que limiten esa movilidad. Identifique ENgage Wildland en la requisición para evitar que un conjunto estructural LION sustituya esta prenda.',
  'traje-morning-pride-tails': 'TAILS admite una especificación institucional detallada, por lo que conviene anexar una matriz de cierre, bolsillo, refuerzo y ribete para cada talla. Con ello se evita mezclar alternativas de una corporación anterior con la configuración que realmente requiere la nueva dotación.',
  'traje-morning-pride-viper': 'La decisión entre rodilla Heat-channel, BiFlex o 3D BiFlex debe basarse en las tareas de la cuadrilla, no en el nombre VIPER. Documente el tipo elegido junto con el cierre y la suspensión, pues esas piezas definen la movilidad y mantenimiento del pantalón ofertado. La cotización debe señalar cuál rodilla VIPER corresponde a cada puesto operativo.',
  'traje-morning-pride-tails-proximity': 'Para TAILS Proximity, programe inventario de piezas de asiento y entrepierna reemplazables con la misma configuración aluminizada del conjunto. Eso permite resolver desgaste localizado sin sustituir componentes de proximidad por telas o refacciones que no correspondan al diseño original. Separe esta solicitud de TAILS estructural para preservar la construcción de proximidad en cada reemplazo.',
  'traje-morning-pride-viper-proximity': 'VIPER Proximity requiere alinear la opción TES Nomex con el riesgo de calor radiante definido por la instalación. Registre el compuesto completo, la fecha de entrega y las instrucciones de cuidado para asegurar que futuras reposiciones mantengan el mismo desempeño del conjunto original. Distinga VIPER Proximity del VIPER estructural en la orden, aun cuando compartan componentes de movilidad.',
  'firedex-tecgen71-estructural': 'En FXR con TECGEN71, la matriz de compra debe ligar cada valor térmico al código de barrera y forro. Así se evita adjudicar por un TPP o THL publicado para CORECXP y CROSSTECH Prime cuando la oferta entregará una combinación distinta de Fire-Dex.',
  'firedex-tecgen51-estructural': 'La dotación TECGEN51 debe separar inventario Standard y Deluxe para que cada turno reciba las características solicitadas. Cuando se elija overol, defina además la distribución de radio, micrófono y bolsillos, porque esos puntos cambian la utilidad de la prenda en rescate.',
  'traje-firedex-aeroflex': 'AeroFlex exige revisar que los paneles VaporLite permanezcan en las zonas previstas y que las ventilas no estén obstruidas durante el mantenimiento. La configuración debe conservar el sistema de rodilla y las ubicaciones de panel descritas por Fire-Dex para no alterar el diseño ventilado.',
  'traje-firedex-proximity': 'En Proximity Turnouts, el largo de chaquetón debe seleccionarse junto con el panel trasero del pantalón para conservar solape en movimientos de ARFF. La cuadrilla debe saber si utilizará cubierta y faldón de casco, pues son accesorios que modifican la configuración de protección. Especifique Fire-Dex Proximity Turnouts por nombre para no sustituirlo por un conjunto FXR estructural.',
  'traje-firedex-wildland': 'Wildland debe especificar la organización de herramientas y radio en sus bolsillos antes de elegir dos piezas u overol. El refuerzo de rodilla y los ajustes de puño deben responder al terreno de trabajo, evitando adaptar esta prenda forestal con requerimientos propios de bunker estructural.',
  'skold-hero-pbi-estructural': 'Herö debe documentar el número MH60435 junto con las etiquetas individuales y el registro de vida útil de chaquetón y pantalón. Si se piden refuerzos Stedshield, cuello escudo o DRD, incorpórelos a la misma configuración para que la dotación mantenga sus componentes de rescate.',
  'skold-defender-brigadista': 'Defender permite planear inventario de FPJ01, FPP01 y FPT01 para reparar o sustituir sólo la pieza dañada. La brigada debe conservar la declaración de equivalencia junto con cada FPKIT, especialmente cuando la compra forma parte de un expediente industrial auditable. Solicite las tres referencias por escrito cuando se cotice el FPKIT completo.',
  'skold-forestal-nomex': 'Para Forestal, mantenga juntas las referencias FPFTJ y FPFTP en el expediente, aunque se repongan por separado. El repelente al agua y el tejido Nomex IIIA deben verificarse en la orden de cada lote para conservar la misma especificación durante varias temporadas de incendio. La reposición debe conservar las referencias Forestal, no una prenda Nomex sin el mismo conjunto.',
  'skold-aproximacion-aluminizado': 'La selección FPAPROX91 o FPAPROX13 debe coincidir con la barrera declarada y los accesorios de aproximación del usuario. Guante, cubrecasco y conjunto aluminizado deben revisarse como sistema, porque el calor radiante no se limita a la tela del chaquetón o pantalón. Indique la versión FPAPROX elegida para evitar combinar una barrera distinta en reposiciones posteriores.',
  'skold-overol-rescate': 'El Overol de Rescate debe registrar la ubicación de bordados, impresión y reflejante antes de producirlo. Los bolsillos de radio, carga y las presillas permiten adaptar la prenda a herramientas de rescate, pero no sustituyen protección adicional cuando el riesgo exige otro tipo de EPP.',
};

const complementoSeleccionR9Lote3: Record<string, string> = {
  'scba-msa-g1-estructural': 'La muestra debe mostrar la etiqueta de aprobación y la identificación de cada módulo; con ella el comité puede contrastar cilindro, duración nominal y electrónica sin sustituir una versión aprobada por otra parecida.',
  'scba-msa-g1-industrial': 'Durante la prueba, documente consumo de aire, relevo y recarga con la duración nominal elegida. Ese registro permite dimensionar cilindros de reemplazo sin interpretar los 60 minutos como disponibilidad fija para todos los usuarios.',
  'scba-msa-g1-cbrn': 'Mantenga la documentación CBRN junto con la lista de piezas de cada unidad. Así, las reposiciones pueden verificarse contra la aprobación completa en vez de depender de la denominación comercial de la plataforma.',
  'scba-msa-g1-rit': 'La cuadrilla debe listar por separado los componentes que exige su propio procedimiento de intervención rápida. Esto permite recibir un G1 documentado y un recurso RIT definido, sin mezclar responsabilidades en una sola descripción.',
  'scba-drager-pss7000-estructural': 'Pruebe ajuste de la placa dorsal en sus tres posiciones con la careta y el cilindro elegidos. Esta comprobación práctica determina la configuración corporal, mientras Sentinel sigue aportando información de estado durante la operación.',
  'scba-drager-pss7000-industrial': 'Incluya una demostración de desmontaje, limpieza y reinspección del arnés antes de aceptar el equipo. El programa de mantenimiento debe usar las instrucciones Dräger para los materiales y componentes realmente suministrados.',
  'scba-drager-pss7000-nfpa': 'Conserve el número de serie, la etiqueta y la configuración del PSS en el expediente de cada usuario. Esa trazabilidad ayuda a detectar una combinación de regulador, cilindro o monitor que no corresponda a la aprobación.',
  'scba-drager-pss7000-rit': 'Ensaye el despliegue del recurso adicional que utilice la corporación junto al PSS 7000 adquirido. La compatibilidad táctica se demuestra con ese conjunto real, no a partir del nombre RIT de esta ficha.',
  'scba-3m-scott-air-pak-x3-pro': 'Antes de implementar ePAR, defina quién administra Monitor Pro, la conectividad y el acceso a registros. De esa forma la electrónica Bluetooth se integra a una política de rendición de cuentas realmente operable.',
  'casco-msa-gallet-f1xf': 'Evalúe el campo visual y la interacción del visor con la careta, iluminación y comunicaciones autorizadas. La decisión debe conservar las homologaciones europeas declaradas para F1 XF, incluso después de seleccionar accesorios, etiquetas, retenedor y cubrenuca aplicables.',
  'casco-msa-gallet-f2xr': 'Realice una prueba por cada misión prevista: forestal, vial, rescate técnico o agua. El mismo nombre F2XR no reemplaza comprobar la retención, visor y accesorios que correspondan a cada entorno, ni confirmar la talla con guantes y protección auditiva del personal operativo asignado.',
  'casco-bullard-ustm-nfpa1970': 'Incluya en la muestra el acabado mate solicitado y los accesorios completos. Esto evita recibir una unidad UST brillante o sin el sistema ocular que la corporación evaluó durante la comparación, ni con una suspensión diferente a la probada por sus usuarios de guardia en entrenamiento.',
  'casco-bullard-ust-lowrider': 'Mida la interacción del casco con el respaldo del SCBA, el cuello del turnout y la máscara durante movimientos reales. La reducción de altura sólo aporta valor si esas interfaces mantienen la cobertura y retención esperadas.',
  'casco-cairns-n6a-houston-nfpa1970': 'Programe inspección del cuero y reemplazo de elementos blandos bajo la guía Cairns. La apariencia tradicional no elimina el control de retención, impactos, contaminación ni la revisión antes de cada asignación operativa o cambio de usuario responsable de turno.',
  'casco-cairns-1836': 'Capacite a la dotación para reconocer el sistema Shell Release y revisar sus componentes antes de uso. El casco debe volver a servicio únicamente cuando shell, tapa de impacto y sujeciones permanezcan íntegros.',
  'casco-msa-gallet-f2-xtrem': 'El mantenimiento debe seguir el manual F2 X-TREM y evitar adaptaciones ajenas a MSA. El fabricante advierte que un casco sometido a impacto severo debe reemplazarse aunque el daño no sea inmediatamente visible durante inspección rutinaria posterior formal.',
  'casco-cairns-xf1': 'Pruebe cada talla XF1 con la pantalla y el sistema de retención instalados. Los pesos publicados corresponden al casco con pantalla y sin opciones, por lo que accesorios posteriores cambian la evaluación de la unidad.',
  'casco-bullard-usrx': 'Elija la protección ocular con los guantes y la máscara que realmente usa la brigada. Quick-Attach permite cambios de equipo compatible, pero no sustituye comprobar que la configuración seleccionada se mantenga asegurada bajo movimiento y calor en escena.',
  'casco-bullard-wildfire': 'Use el peso y la forma publicados específicamente para FH911C al calcular carga de cabeza. Las versiones de sombrero y XL pertenecen a la misma familia, pero no comparten necesariamente esa masa ni geometría.',
  'casco-bullard-fx': 'Cuando se solicite proximidad, reciba la configuración AX o FX identificada con todos sus accesorios térmicos. Un casco estructural FX ordinario no adquiere esa condición por añadir una referencia comercial posterior ni por cambiar sólo el visor, cubrenuca o acabado exterior durante mantenimiento preventivo institucional programado.',
  'casco-bullard-px': 'Incluya revisión de cubrenuca, retenedor y visor después de cada ciclo de lavado. El propósito de que sean removibles es facilitar cuidado, no autorizar cambios con piezas incompatibles de otra plataforma.',
  'casco-bullard-lt': 'La compra debe quedar condicionada a recibir documentación contemporánea del LT ofertado. Esto protege al comprador contra adjudicar una edición histórica de NFPA o una combinación de accesorios que ya no corresponda al modelo suministrado para su institución operativa.',
  'casco-bullard-ax': 'Revise el estado de las superficies aluminizadas y del visor dorado dentro del programa de cuidado de proximidad. Cambios de color, desprendimientos o daño deben evaluarse con las instrucciones Bullard antes de continuar uso operativo en respuesta ARFF o ejercicios de capacitación controlada.',
  'casco-cairns-880': 'Conserve el número de parte de cada 880 junto con la talla y accesorios entregados. Esa práctica evita reemplazar una configuración de goggles o Bourkes por otra que sólo comparte el nombre del casco.',
  'casco-cairns-invader-664': 'Antes de adoptar una talla, pruebe el ajuste del headband con la máscara SCBA institucional. El rango publicado ayuda a elegir, pero una revisión física confirma que visor, capucha y retención trabajen como conjunto.',
  'casco-cairns-360s': 'La corporación debe conservar la descripción de la configuración estándar junto a la etiqueta individual. Así podrá comprobar visor, barboquejo, earlap y reflejantes sin atribuir al 360S piezas que pertenezcan a otro Cairns durante futuras reposiciones institucionales, auditorías de EPP o ejercicios de asignación de equipo.',
  'casco-cairns-660c-traditional': 'Seleccione color, visor y liner por el número de parte concreto del 660C. Las siete opciones de color no definen por sí mismas qué protector facial o accesorios de proximidad acompañan la unidad recibida.',
};

for (const producto of featuredProducts) {
  const ficha = enriquecimientoTrajes[producto.slug]
    ?? enriquecimientoR9Lote2[producto.slug]
    ?? enriquecimientoR9Lote2Rescate[producto.slug]
    ?? enriquecimientoR9Lote2Drones[producto.slug]
    ?? enriquecimientoR9Lote3Scba[producto.slug]
    ?? enriquecimientoR9Lote3Cascos[producto.slug];
  if (ficha) Object.assign(producto, ficha);
  const detalle = detalleSeleccionPorModelo[producto.slug];
  if (detalle && producto.seleccion) producto.seleccion.push(detalle);
  const complemento = complementoSeleccionR9Lote3[producto.slug];
  if (complemento && producto.seleccion) producto.seleccion.push(complemento);
}
